// Package broker provides transport-agnostic, generic messaging functions.
//
// A Channel[T] describes where messages of type T travel. Publish, Subscribe,
// Request and Respond work on any channel and any payload type; the
// transport is a small Broker interface (see natsbroker for NATS). Code
// generated by asyncapi-gen only declares models, channels and a thin client
// that calls these functions.
package broker

import "context"

// Broker is the transport underneath a Client.
type Broker interface {
	// Publish sends m to m.Subject.
	Publish(ctx context.Context, m *Message) error
	// Request sends m and waits for a single reply. ctx carries the deadline.
	Request(ctx context.Context, m *Message) (*Message, error)
	// Subscribe calls h for every message matching subject. Subjects may
	// contain "*" wildcards for single tokens. A non-empty queue load
	// balances messages across subscribers sharing that queue name.
	//
	// h returns nil when the message was handled. Brokers with
	// acknowledgements (see jsbroker) ack on nil, redeliver on an error, and
	// drop messages whose error wraps ErrMalformed. Others ignore it.
	Subscribe(subject, queue string, h func(*Message) error) (Subscription, error)
}

// Endpoint is where a receive operation listens: the subject pattern and
// queue name it passes to Broker.Subscribe. Generated code declares one per
// receive operation, e.g. to create or bind JetStream consumers.
type Endpoint struct {
	Subject string
	Queue   string
}

// Subscription is an active subscription.
type Subscription interface {
	Unsubscribe() error
}

// Message is a message as carried by a Broker.
type Message struct {
	Subject string
	// Reply is the subject a response should be published to, if any.
	Reply  string
	Header Header
	Data   []byte
}

// Header holds message headers.
type Header map[string][]string

// Get returns the first value of key, or "".
func (h Header) Get(key string) string {
	if v := h[key]; len(v) > 0 {
		return v[0]
	}
	return ""
}

// Set replaces the values of key.
func (h Header) Set(key, value string) { h[key] = []string{value} }
